_TRUE  = ["YES", "Y", "TRUE", "1", "1.0"]
_FALSE = ["NO",  "N", "FALSE", "0", "0.0"]


def _as_str(c):
    return F.trim(F.col(f"`{c}`").cast("string"))


def build_col(src, kind):
    s = _as_str(src)
    if kind == "str":
        return F.when(s == "", None).otherwise(s)
    if kind in ("id", "idz"):
        t = F.regexp_replace(s, r"\.0+$", "")
        if kind == "idz":
            return F.when(t.isin("", "0"), None).otherwise(t)
        return F.when(t == "", None).otherwise(t)
    if kind == "long":
        return s.cast("decimal(20,0)").cast("bigint")
    if kind == "int":
        return s.cast("decimal(20,0)").cast("int")
    if kind == "dec":
        return s.cast("decimal(18,3)")
    if kind == "ts":
        return F.coalesce(*[F.to_timestamp(s, f) for f in TS_FORMATS])
    if kind == "flag":
        u = F.upper(s)
        return (F.when(u.isin(_TRUE), F.lit(1))
                 .when(u.isin(_FALSE), F.lit(0))
                 .otherwise(None)
                 .cast("byte"))
    raise ValueError(kind)


# yard slot as it appears in locSlot / laden_LocSlot:  <block><bay>.. e.g. "3E53C.4"
#   block=3E  bay=53  row=C  tier=4.  Vessel slots (e.g. "230308") are left unparsed.
YARD_SLOT_RE = r"^(\d?[A-Z]{1,2})(\d{2,3})([A-Z])\.(\d{1,2})$"

def add_slot_parts(df, col, prefix):
    c = F.col(col)
    def part(i):
        v = F.regexp_extract(c, YARD_SLOT_RE, i)
        return F.when(v == "", None).otherwise(v)
    return (
        df
        .withColumn(f"{prefix}_block", part(1))
        .withColumn(f"{prefix}_bay",   part(2))
        .withColumn(f"{prefix}_row",   part(3))
        .withColumn(f"{prefix}_tier",  part(4).cast("smallint"))
